class Solution {
public:
    vector<int> numsSameConsecDiff(int n, int k) {
        vector<int> result;
        for (int d = 1; d <= 9; d++) {
            dfs(d, 1, n, k, result);
        }
        return result;
    }
private:
    void dfs(int num, int len, int n, int k, vector<int>& result) {
        if (len == n) {
            result.push_back(num);
            return;
        }
        int last = num % 10;
        int hi = last + k;
        if (hi <= 9) {
            dfs(num * 10 + hi, len + 1, n, k, result);
        }
        int lo = last - k;
        if (lo >= 0 && lo != hi) {
            dfs(num * 10 + lo, len + 1, n, k, result);
        }
    }
};
